 private void cancelSearch(){handler.removeCallbacks(tapWarm);TapPreparation.cancel(tapOwner);searchGeneration++;searching=false;if(searchJob!=null)searchJob.cancel(true);String old=searchProcess;if(!old.isEmpty())searchControl.execute(()->{MusicCatalog.cancel(old);AccountMusic.cancel(old);try{com.yausername.youtubedl_android.YoutubeDL.getInstance().destroyProcessById(old);}catch(Exception ignored){}});searchProcess="";}
 private void startSearch(){startSearch(false);}
 private void startSearch(boolean refresh){
  hideKeyboard();String q=query.getText().toString().trim();
  if(q.isEmpty()){message("Enter a song, artist, or YouTube link.");return;}if(q.length()>200){message("Keep your search under 200 characters.");return;}
  cancelSearch();int generation=searchGeneration;String kind=searchKind;String cacheKey="videos".equals(kind)?"video|"+q:q;submittedQuery=q;searchCached=false;RecentHistory.touch(this,"recentQueries",q);page="search";message("");
  List<Track> cached=refresh?null:searchCache.get(cacheKey,android.os.SystemClock.elapsedRealtime());if(cached!=null){queue=cached;searchCached=true;showResults(queue);message("Saved results · Refresh checks YouTube again");return;}
  searching=true;showResults(List.of());String process="search-"+UUID.randomUUID();searchProcess=process;
  searchJob=searchWorker.submit(()->{try{List<Track> found=searchSource.find(q,process);runOnUiThread(()->{if(isDestroyed()||generation!=searchGeneration)return;searching=false;searchProcess="";searchCache.put(cacheKey,found,android.os.SystemClock.elapsedRealtime());MusicTaste.remember(this,found);queue=found;if("songs".equals(kind)&&!q.contains("://")&&!found.isEmpty())getSharedPreferences("music",0).edit().putString("recommendationSeed",q).apply();if("search".equals(page)){showResults(found);NativeMotion.reveal(results);message(found.isEmpty()?"Nothing online matched. Try a different song or artist.":found.size()+" online results");}});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||generation!=searchGeneration)return;searching=false;searchProcess="";queue=new ArrayList<>();if("search".equals(page)){showResults(queue);message("Search unavailable. "+DownloadErrors.friendly(e.getMessage()));}});}});
 }

 private void navigate(String destination){handler.removeCallbacks(tapWarm);TapPreparation.cancel(tapOwner);
  page=destination;hideKeyboard();message("");
  if("home".equals(page))showHome();else if("library".equals(page))showLibrary();else showResults(queue);
  scroll.scrollTo(0,0);NativeMotion.reveal(results);
 }
 private void selectTab(boolean ignored){if(navigationBar!=null)navigationBar.getMenu().findItem("home".equals(page)?1:"search".equals(page)?2:3).setChecked(true);}
 private void message(String value){status.setText(value);status.setVisibility(value.isEmpty()?View.GONE:View.VISIBLE);}
 private void hideKeyboard(){((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);query.clearFocus();}
 private TextView caption(String value){TextView t=text(value,12);t.setTextColor(MUTED);return t;}
