 private void addMixHero(List<Track> tracks){boolean account=Recommendations.account(this);List<DiscoveryShelf> shelves=Recommendations.shelves(this);com.google.android.material.card.MaterialCardView card=UiComponents.card(this,RADIUS_SHEET);LinearLayout body=row();body.setPadding(dp(SPACE_16),dp(SPACE_16),dp(SPACE_16),dp(SPACE_16));body.setMinimumHeight(dp(SIZE_HERO));LinearLayout words=column();TextView eyebrow=caption(account?"YOUR YOUTUBE MUSIC":"LOCAL MUSIC PICKS");eyebrow.setTextColor(COLOR_ACCENT);words.addView(eyebrow);TextView title=text(account?(shelves.isEmpty()?"Your account picks":shelves.get(0).title):"Local music mix",TYPE_SECTION);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setPadding(0,dp(SPACE_8),0,dp(SPACE_4));words.addView(title);TextView hint=caption(account?(tracks.isEmpty()?"Refresh to load music from your connected account.":tracks.size()+(tracks.size()==1?" song":" songs")+" · from your YouTube Music"):"Connect YouTube for account-based recommendations.");hint.setMaxLines(2);words.addView(hint);words.addView(UiComponents.action(this,tracks.isEmpty()?(account?"Refresh account":"Connect YouTube"):"Play mix",tracks.isEmpty()?R.drawable.ic_lucide_sliders_horizontal:R.drawable.ic_lucide_play,true,()->{if(tracks.isEmpty()){if(account)refreshDiscovery(true);else showYouTubeAccount();}else playSongCollection(tracks);}));body.addView(words,weight());LinearLayout covers=column();for(int row=0;row<2;row++){LinearLayout pair=row();for(int col=0;col<2;col++){int index=row*2+col;ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);art.setBackground(GlassTheme.coverFrame(this));art.setClipToOutline(true);art.setContentDescription("Mix artwork");if(index<tracks.size())Artwork.load(this,tracks.get(index),art,dp(SIZE_COVER));else art.setImageDrawable(new TrackCoverDrawable(index%2==0?"Pocket":"Music"));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(SIZE_COVER),dp(SIZE_COVER));p.setMargins(dp(SPACE_4),dp(SPACE_4),0,0);pair.addView(art,p);}covers.addView(pair);}LinearLayout.LayoutParams picture=new LinearLayout.LayoutParams(dp(SIZE_HERO_ART),-2);picture.leftMargin=dp(SPACE_12);body.addView(covers,picture);card.addView(body);LinearLayout.LayoutParams margin=new LinearLayout.LayoutParams(-1,-2);margin.topMargin=dp(SPACE_12);margin.bottomMargin=dp(SPACE_4);results.addView(card,margin);}
