 private List<File> recentFiles(List<File> available){List<File> recent=new ArrayList<>();for(String path:RecentHistory.read(this,"recentTracks"))for(File f:available)if(f.getAbsolutePath().equals(path)&&!recent.contains(f))recent.add(f);return recent;}
