 private String homeGreeting(){int hour=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);return hour<12?"Good morning":hour<18?"Good afternoon":"Good evening";}
 private View trackRow(File file){
  Track catalog=knownMusic.get(TrackFiles.videoId(file));String display=catalog==null?TrackFiles.title(file):catalog.title;
  LinearLayout entry=row();entry.setPadding(dp(SPACE_4),dp(SPACE_8),0,dp(SPACE_8));entry.setMinimumHeight(dp(SIZE_ROW));entry.addView(localArtwork(file,SIZE_COVER));
  LinearLayout words=column();words.setPadding(dp(SPACE_12),0,dp(SPACE_8),0);TextView name=text(display,TYPE_BODY);name.setTypeface(null,android.graphics.Typeface.BOLD);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);words.addView(name);TextView source=caption((catalog!=null&&!catalog.artist.isEmpty()?catalog.artist:TrackFiles.audio(file)?"Audio":"Video")+" · "+formatSize(file.length()));source.setPadding(0,dp(SPACE_4),0,0);words.addView(source);words.setMinimumHeight(dp(SIZE_TOUCH));words.setGravity(Gravity.CENTER_VERTICAL);words.setContentDescription((TrackFiles.audio(file)?"Play ":"Open ")+TrackFiles.title(file));words.setOnClickListener(v->openTrack(file));entry.addView(words,weight());
  Button more=ghostButton("⋮",()->trackMenu(file));more.setContentDescription("Track options for "+TrackFiles.title(file));entry.addView(more,new LinearLayout.LayoutParams(dp(SIZE_TOUCH),dp(SIZE_TOUCH)));entry.setOnClickListener(v->openTrack(file));entry.setBackground(GlassTheme.row(this));return entry;
 }
 private void openTrack(File file){if(TrackFiles.audio(file))playLocal(file);else openVideo(file);}

 private String formatSize(long bytes){return String.format(Locale.ROOT,"%.1f MB",bytes/1048576.0);}
 private void showLibrary(){
  page="library";selectTab(true);section.setText("Library");input.setVisibility(View.GONE);results.removeAllViews();indexLocalCopies();if("liked".equals(libraryMedia)){showLikedCollection();return;}
  List<File> all=MusicRepository.files(this);long bytes=0;for(File file:all)bytes+=file.length();TextView overview=caption(trackCount(all.size())+" · "+formatSize(bytes)+" · on this device");overview.setPadding(0,dp(SPACE_4),0,dp(SPACE_16));results.addView(overview);
  LinearLayout collection=row();collection.setPadding(0,dp(SPACE_8),0,dp(SPACE_8));ImageButton heart=UiComponents.icon(this,R.drawable.ic_lucide_heart,"Open liked songs",()->{libraryMedia="liked";showLibrary();});collection.addView(heart,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout label=column();TextView liked=text("Liked songs",TYPE_TITLE);liked.setTypeface(null,android.graphics.Typeface.BOLD);label.addView(liked);label.addView(caption("Your favorites, together"));collection.addView(label,weight());collection.addView(ghostButton("Open",()->{libraryMedia="liked";showLibrary();}));collection.setOnClickListener(v->{libraryMedia="liked";showLibrary();});results.addView(collection);results.addView(ghostButton("Smart downloads · "+SmartDownloads.files(this).size()+" songs",this::showSmartDownloads));
  EditText filter=new EditText(this);filter.setSingleLine(true);filter.setTextSize(TYPE_BODY);filter.setTextColor(COLOR_TEXT);filter.setHintTextColor(COLOR_TEXT_MUTED);filter.setHint("Find in your library");filter.setContentDescription("Search downloaded tracks");filter.setBackground(GlassTheme.input(this));filter.setPadding(dp(16),0,dp(16),0);filter.setText(libraryQuery);LinearLayout.LayoutParams find=new LinearLayout.LayoutParams(-1,dp(48));find.topMargin=dp(12);find.bottomMargin=dp(12);results.addView(filter,find);
  LinearLayout filters=row();String[] names={"Everything","Audio","Video"},values={"all","audio","video"};for(int i=0;i<names.length;i++){String value=values[i];com.google.android.material.chip.Chip chip=UiComponents.chip(this,names[i],libraryMedia.equals(value),()->{libraryMedia=value;showLibrary();});LinearLayout.LayoutParams space=new LinearLayout.LayoutParams(-2,-2);space.rightMargin=dp(8);filters.addView(chip,space);}results.addView(filters);
  LinearLayout summary=row();summary.setPadding(0,dp(12),0,dp(4));libraryCount=caption("");summary.addView(libraryCount,weight());Button sort=ghostButton(libraryByName?"Title  ↓":"Newest  ↓",this::chooseLibrarySort);sort.setContentDescription("Sort library");summary.addView(sort);results.addView(summary);
  libraryRows=column();results.addView(libraryRows);renderLibraryRows();filter.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence value,int start,int before,int count){libraryQuery=value.toString();renderLibraryRows();}public void afterTextChanged(android.text.Editable e){}});
 }
 private String trackCount(int count){return count+(count==1?" track":" tracks");}
 private List<File> librarySelection(){List<File> shown=LibraryOrder.select(MusicRepository.files(this),libraryMedia,libraryByName);String query=libraryQuery.trim().toLowerCase(Locale.ROOT);if(!query.isEmpty())shown.removeIf(file->{Track song=knownMusic.get(TrackFiles.videoId(file));return !(TrackFiles.title(file)+" "+(song==null?"":song.title+" "+song.artist)).toLowerCase(Locale.ROOT).contains(query);});return shown;}
 private void renderLibraryRows(){if(libraryRows==null)return;libraryRows.removeAllViews();List<File> shown=librarySelection();libraryCount.setText(trackCount(shown.size()));List<File> audio=new ArrayList<>();for(File file:shown)if(TrackFiles.audio(file))audio.add(file);if(!audio.isEmpty()){Button playAll=UiComponents.action(this,"Play all",R.drawable.ic_lucide_play,true,()->playLocalCollection(audio));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(56));p.bottomMargin=dp(12);libraryRows.addView(playAll,p);}if(shown.isEmpty()){TextView empty=text(libraryQuery.isBlank()?"Your music starts here":"No matching tracks",TYPE_SECTION);empty.setPadding(0,dp(24),0,dp(8));libraryRows.addView(empty);libraryRows.addView(caption(libraryQuery.isBlank()?"Download a song from Search, or import audio from the top menu.":"Try another title or artist."));if(libraryQuery.isBlank())libraryRows.addView(UiComponents.action(this,"Find music",R.drawable.ic_lucide_search,false,()->navigate("search")));return;}for(File file:shown)libraryRows.addView(trackRow(file));}
 private void chooseLibrarySort(){new AlertDialog.Builder(this).setTitle("Order your collection").setSingleChoiceItems(new String[]{"Newest first","Track title"},libraryByName?1:0,(d,which)->{libraryByName=which==1;getSharedPreferences("music",0).edit().putBoolean("libraryByName",libraryByName).apply();d.dismiss();showLibrary();}).setNegativeButton("Close",null).show();}
 private void showResults(List<Track> tracks){
  indexLocalCopies();page="search";selectTab(false);section.setText("Search");input.setVisibility(View.VISIBLE);results.removeAllViews();LinearLayout modes=row();for(String kind:new String[]{"songs","videos"}){com.google.android.material.chip.Chip chip=UiComponents.chip(this,kind.equals("songs")?"Songs":"Videos",searchKind.equals(kind),()->{if(!searchKind.equals(kind)){cancelSearch();searchKind=kind;queue=new ArrayList<>();if(query.getText().toString().isBlank()){submittedQuery="";showResults(queue);}else startSearch();}else showResults(queue);});modes.addView(chip);}results.addView(modes);
  if(!submittedQuery.isEmpty()){String q=submittedQuery.toLowerCase(Locale.ROOT);List<File> local=new ArrayList<>();String id=VideoLinks.id(submittedQuery);for(File f:MusicRepository.files(this))if(TrackFiles.audio(f)&&(TrackFiles.title(f).toLowerCase(Locale.ROOT).contains(q)||(id!=null&&id.equals(TrackFiles.videoId(f)))))local.add(f);if(!local.isEmpty()){titleRow("On this phone",null,null);for(File f:local.subList(0,Math.min(4,local.size())))results.addView(trackRow(f));}}
  if(searching){showSearchLoading();return;}
  if(tracks.isEmpty()){
   if(!submittedQuery.isEmpty()){titleRow("Online results","Refresh",()->startSearch(true));results.addView(caption("No online results to show. Edit your search or try Refresh."));return;}
   List<String> queries=RecentHistory.read(this,"recentQueries");if(!queries.isEmpty()){titleRow("Your recent searches","Clear",()->{RecentHistory.clear(this,"recentQueries");showResults(queue);});for(String q:queries){Button history=ghostButton("↶   "+q,()->searchFor(q));history.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);history.setContentDescription("Search again for "+q);results.addView(history);}}
   ensureRecommendations(false);recommendationShelf();if(Recommendations.account(this))return;titleRow("Try something new",null,null);for(String hint:new String[]{"Acoustic favorites","Nepali music","Jazz for the evening","Instrumental focus"}){Button b=ghostButton(hint+"   ↗",()->searchFor(hint));b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);results.addView(b);}return;
  }
  titleRow(searchCached?"Saved search results":"Online results",submittedQuery.isEmpty()?null:"Refresh",()->startSearch(true));TextView help=caption("songs".equals(searchKind)?"Tap to stream in the background · ↓ saves offline":"Video results · kept separate from music discovery");help.setPadding(0,dp(SPACE_8),0,dp(SPACE_12));results.addView(help);
  for(Track track:tracks)results.addView(onlineTrackRow(track,tracks));scheduleVisibleSongs();
 }
 private View onlineTrackRow(Track track,List<Track> source){
  LinearLayout entry=row();entry.setPadding(0,dp(SPACE_8),0,dp(SPACE_8));ImageView cover=new ImageView(this);cover.setScaleType(ImageView.ScaleType.CENTER_CROP);cover.setImageDrawable(new TrackCoverDrawable(track.title));cover.setBackground(GlassTheme.coverFrame(this));cover.setClipToOutline(true);cover.setContentDescription(track.title+" artwork");entry.addView(cover,new LinearLayout.LayoutParams(dp(SIZE_COVER),dp(SIZE_COVER)));loadArtwork(track.id,cover);
  LinearLayout words=column();words.setPadding(dp(SPACE_12),0,dp(SPACE_4),0);TextView title=text(track.title,TYPE_BODY);title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);title.setTypeface(null,android.graphics.Typeface.BOLD);words.addView(title);String detail=track.subtitle();words.addView(caption(localCopies.containsKey(track.id)?"Saved · plays offline":detail.isEmpty()?"Online audio":detail));words.setMinimumHeight(dp(SIZE_TOUCH));words.setContentDescription("Play "+track.title);words.setOnClickListener(v->playTrack(track,source));entry.addView(words,weight());
  Button download=ghostButton("↓",()->chooseDownload(track));download.setTextSize(TYPE_SECTION);download.setContentDescription("Download "+track.title);entry.addView(download,new LinearLayout.LayoutParams(dp(SIZE_TOUCH),dp(SIZE_TOUCH)));Button more=ghostButton("⋮",()->onlineTrackMenu(track,source));more.setContentDescription("Song options for "+track.title);entry.addView(more,new LinearLayout.LayoutParams(dp(SIZE_TOUCH),dp(SIZE_TOUCH)));entry.setOnClickListener(v->playTrack(track,source));entry.setTag(track);entry.setBackground(GlassTheme.row(this));return entry;
 }
 private void scheduleVisibleSongs(){handler.removeCallbacks(tapWarm);handler.postDelayed(tapWarm,200);}
 private void prepareVisibleSongs(){if(!visible||isDestroyed())return;LocalPlayerService service=LocalPlayerService.active;if(service!=null&&service.pauseAvailable()&&!service.playing()){TapPreparation.cancel(tapOwner);return;}List<Track> candidates=new ArrayList<>();visibleSongs(results,candidates);if(service!=null&&service.playing()&&candidates.size()>1)candidates=new ArrayList<>(candidates.subList(0,1));TapPreparation.plan(this,tapOwner,candidates);}
 private void visibleSongs(View view,List<Track> found){if(found.size()>=2)return;android.graphics.Rect bounds=new android.graphics.Rect();if(!view.getGlobalVisibleRect(bounds))return;if(view.getTag() instanceof Track){Track track=(Track)view.getTag();if(track.music&&!localCopies.containsKey(track.id)&&bounds.height()>=dp(SIZE_TOUCH)/2)found.add(track);return;}if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount()&&found.size()<2;i++)visibleSongs(group.getChildAt(i),found);}}
 private void playTrack(Track track,List<Track> source){File local=localCopies.get(track.id);if(local!=null&&!local.isFile())local=null;if(local!=null){playLocal(local);return;}startOnlineAudio(track,source);}
 private void onlineTrackMenu(Track track,List<Track> source){handler.removeCallbacks(tapWarm);if(track.music&&!localCopies.containsKey(track.id))TapPreparation.plan(this,tapOwner,List.of(track));List<String> labels=new ArrayList<>(List.of("Play","Play next","Add to queue","Watch YouTube preview (foreground)","Download"));if(track.music){labels.add(MusicTaste.liked(this,track.id)?"Remove from liked songs":"Like song");labels.add("Not for me");}new com.google.android.material.dialog.MaterialAlertDialogBuilder(this).setTitle(track.title).setItems(labels.toArray(new String[0]),(d,w)->{if(w==0)playTrack(track,source);else if(w==1||w==2)enqueueTrack(track,w==1);else if(w==3){queue=new ArrayList<>(source);startPreview(track);}else if(w==4)chooseDownload(track);else if(w==5)likeSong(track);else hideSong(track);}).setNegativeButton("Close",null).show();}
 private void likeSong(Track track){boolean liked=MusicTaste.toggleLike(this,track);profileChanged();com.google.android.material.snackbar.Snackbar.make(findViewById(android.R.id.content),liked?"Added to liked songs":"Removed from liked songs",com.google.android.material.snackbar.Snackbar.LENGTH_LONG).setAction("Undo",v->{MusicTaste.toggleLike(this,track);profileChanged();}).show();}
 private void hideSong(Track track){MusicTaste.hide(this,track.id,true);profileChanged();com.google.android.material.snackbar.Snackbar.make(findViewById(android.R.id.content),"Hidden from your recommendations",com.google.android.material.snackbar.Snackbar.LENGTH_LONG).setAction("Undo",v->{MusicTaste.hide(this,track.id,false);profileChanged();}).show();}
 private void profileChanged(){long version=MusicTaste.version(this);if(version!=lastProfileVersion){lastProfileVersion=version;cancelRecommendations();lastFeedAttempt=System.currentTimeMillis();handler.removeCallbacks(profileRefresh);handler.postDelayed(profileRefresh,900);lastRecommendationRequest="";}if("home".equals(page))showHome();else if("library".equals(page)&&"liked".equals(libraryMedia))showLibrary();updateFavorite();}
 private void refreshDiscovery(boolean force){if(recommendationsLoading)return;lastFeedAttempt=0;ensureRecommendations(force);if("home".equals(page))showHome();else if("search".equals(page))showResults(queue);}
 private Track activeSong(){if(streaming)return current;LocalPlayerService player=LocalPlayerService.active;if(player==null)return null;if(player.online)return player.song;String id=TrackFiles.videoId(new File(player.path));if(id==null)return null;Track known=knownMusic.get(id);if(known!=null)return known;if(!id.equals(cachedActiveId)){cachedActiveId=id;cachedActiveSong=MusicTaste.track(this,id);}return cachedActiveSong;}
 private boolean currentLiked(){Track track=activeSong();LocalPlayerService player=LocalPlayerService.active;String identity=track!=null?track.id:player==null?"":player.path;String key=identity+"|"+MusicTaste.version(this)+"|"+getSharedPreferences("music",0).getLong("tasteLocalVersion",0);if(key.equals(favoriteStateKey))return favoriteState;favoriteStateKey=key;favoriteState=track!=null?MusicTaste.liked(this,track.id):player!=null&&!player.path.isEmpty()&&MusicTaste.localLiked(this,new File(player.path));return favoriteState;}
 private void toggleCurrentLike(){Track track=activeSong();if(track!=null&&track.music){likeSong(track);return;}LocalPlayerService player=LocalPlayerService.active;if(player!=null&&!player.online){boolean liked=MusicTaste.toggleLocal(this,new File(player.path));message(liked?"Added to liked songs":"Removed from liked songs");profileChanged();}else message("Like songs from the Songs catalogue to shape your music picks.");}
 private void updateFavorite(){if(favoriteButton==null)return;boolean liked=currentLiked();favoriteButton.setImageTintList(android.content.res.ColorStateList.valueOf(liked?COLOR_DANGER:COLOR_TEXT_MUTED));favoriteButton.setContentDescription(liked?"Unlike current song":"Like current song");favoriteButton.setSelected(liked);LocalPlayerService nativePlayer=LocalPlayerService.active;favoriteButton.setEnabled(streaming?current!=null&&current.music:nativePlayer==null||!nativePlayer.online||nativePlayer.song!=null&&nativePlayer.song.music);favoriteButton.setAlpha(favoriteButton.isEnabled()?1f:.4f);}

 private void enqueueTrack(Track track,boolean next){
  if(streaming){int index=-1;for(int i=0;i<previewQueue.size();i++)if(previewQueue.get(i).id.equals(track.id)){index=i;break;}if(index==previewOrder.current()){message("This song is already playing.");return;}if(index>=0){if(next)previewOrder.playNext(index);}else{previewQueue.add(track);previewOrder.append(next);}message(next?"Playing next: "+track.title:"Added to preview queue");return;}
  if(LocalPlayerService.active!=null&&LocalPlayerService.active.online){message(LocalPlayerService.active.enqueueOnline(track,next)?next?"Playing next: "+track.title:"Added to online queue":"This song is already playing or the queue is full.");return;}
  File local=localCopies.get(track.id);if(local!=null&&!local.isFile())local=null;if(LocalPlayerService.active!=null&&local!=null){message(LocalPlayerService.active.enqueue(local,next)?next?"Playing next: "+track.title:"Added to local queue":"This song is already playing.");return;}
  message(LocalPlayerService.active!=null?"Play this online song first to start a background audio queue.":"Play a song first, then add more from song options.");
 }

 private void showSearchLoading(){
  TextView hint=caption("Looking for your music…");hint.setPadding(0,dp(SPACE_12),0,dp(SPACE_16));results.addView(hint);
  for(int i=0;i<3;i++){LinearLayout placeholder=row();placeholder.setPadding(dp(SPACE_12),dp(SPACE_16),dp(SPACE_12),dp(SPACE_16));placeholder.setMinimumHeight(dp(SIZE_ROW));placeholder.setBackground(GlassTheme.tile(this,COLOR_SURFACE,COLOR_BG));TextView dots=text("— — —",TYPE_BODY);dots.setTextColor(COLOR_BORDER);placeholder.addView(dots);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(SPACE_8);results.addView(placeholder,p);}
 }

 private void showDownloads(){if(downloadsDialog!=null&&downloadsDialog.isShowing()){downloadsDialog.refresh();return;}downloadsDialog=new DownloadsSheet(this,new DownloadsSheet.Actions(){public void play(File file){playLocalCollection(List.of(file));}public void library(){libraryMedia="all";navigate("library");}public void folder(){pickFolder();}public void smart(){showSmartDownloads();}});downloadsDialog.show();}
 private void updateDownloads(){if(downloadsDialog!=null&&downloadsDialog.isShowing())downloadsDialog.refresh();}
 private void showSleepTimer(){long remaining=SleepTimer.remaining(this);String heading=remaining>0?"Sleep timer · "+((remaining+59999)/60000)+" min left":"Sleep timer";String[] labels={"15 minutes","30 minutes","45 minutes","60 minutes","90 minutes","Turn off"};int[] minutes={15,30,45,60,90,0};new AlertDialog.Builder(this).setTitle(heading).setItems(labels,(d,which)->{SleepTimer.set(this,minutes[which]*60000L);message(minutes[which]==0?"Sleep timer off":"Playback will pause in "+minutes[which]+" minutes.");}).setNegativeButton("Close",null).show();}
 private void addWidget(){android.appwidget.AppWidgetManager manager=android.appwidget.AppWidgetManager.getInstance(this);if(manager.isRequestPinAppWidgetSupported())manager.requestPinAppWidget(new ComponentName(this,MusicWidget.class),null,null);else message("Long-press your home screen → Widgets → Pocket Music player.");}
 private void showSuggestions(String queryText){
  if(!"search".equals(page)||searching||queryText.equals(submittedQuery))return;
  if(queryText.trim().isEmpty()){submittedQuery="";queue=new ArrayList<>();showResults(queue);return;}
  List<String> titles=new ArrayList<>();for(File f:MusicRepository.files(this))titles.add(TrackFiles.title(f));List<String> suggestions=SearchSuggestions.build(queryText,RecentHistory.read(this,"recentQueries"),titles);results.removeAllViews();titleRow("Search suggestions",null,null);Button exact=ghostButton("Search for “"+queryText+"”",this::startSearch);exact.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);results.addView(exact);for(String suggestion:suggestions){Button b=ghostButton(suggestion+"   ↗",()->searchFor(suggestion));b.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);results.addView(b);}
 }
 private void ensureRecommendations(boolean force){if(recommendationsLoading||(!force&&Recommendations.fresh(this))||(!force&&System.currentTimeMillis()-lastFeedAttempt<60000L))return;lastFeedAttempt=System.currentTimeMillis();recommendationsLoading=true;recommendationsError="";int generation=feedGeneration;String process="music-discovery-"+UUID.randomUUID();feedProcess=process;recommendationJob=discovery.submit(()->{if(generation!=feedGeneration)return;String error="";try{Recommendations.fetch(this,process,recommendationSource);}catch(Exception e){error=DownloadErrors.rateLimited(e.getMessage())?"The music catalogue is limiting requests. Try later.":Recommendations.account(this)?AccountMusic.friendly(e)+" Cached account picks are kept.":"Music couldn't refresh. Cached songs are kept; check your connection and retry.";}final String notice=error;runOnUiThread(()->{if(isDestroyed()||generation!=feedGeneration)return;recommendationsLoading=false;feedProcess="";recommendationsError=notice;int y=scroll.getScrollY();if("home".equals(page))showHome();else if("search".equals(page)&&!searching&&query.getText().toString().isBlank()&&queue.isEmpty())showResults(queue);scroll.post(()->scroll.scrollTo(0,y));if(force)message(notice.isEmpty()?"Music picks updated":notice);});});}
