 private void showLikedCollection(){titleRow("Liked songs","Back",()->{libraryMedia="all";showLibrary();});List<Track> likes=MusicTaste.liked(this);List<File> files=new ArrayList<>();for(File f:MusicRepository.files(this))if(TrackFiles.audio(f)&&MusicTaste.localLiked(this,f))files.add(f);if(likes.isEmpty()&&files.isEmpty()){TextView empty=text("Keep your favorites close",TYPE_SECTION);empty.setPadding(0,dp(SPACE_24),0,dp(SPACE_12));results.addView(empty);results.addView(caption("Tap the heart or choose Like song from a song’s menu. Your favorites will appear here."));results.addView(UiComponents.action(this,"Find songs",R.drawable.ic_lucide_search,true,()->{searchKind="songs";navigate("search");}));return;}results.addView(UiComponents.action(this,"Play liked",R.drawable.ic_lucide_play,true,()->{if(likes.isEmpty())playLocalCollection(files);else playSongCollection(likes);}));for(Track track:likes)results.addView(onlineTrackRow(track,likes));Set<String> listed=new HashSet<>();for(Track track:likes)listed.add(track.id);for(File file:files)if(!listed.contains(TrackFiles.videoId(file)))results.addView(trackRow(file));}
 private void playSongCollection(List<Track> tracks){if(tracks.isEmpty())return;List<File> local=new ArrayList<>();for(Track track:tracks){File f=localCopies.get(track.id);if(f==null||!f.isFile()){local.clear();break;}local.add(f);}if(local.size()==tracks.size()){playLocalCollection(local);return;}startOnlineAudio(tracks.get(0),tracks);}
 private void playLocalCollection(List<File> files){if(files.isEmpty())return;closePreview();ArrayList<String> paths=new ArrayList<>();for(File f:files)paths.add(f.getAbsolutePath());startForegroundService(new Intent(this,LocalPlayerService.class).setAction("open").putExtra("path",paths.get(0)).putStringArrayListExtra("queuePaths",paths));now.setText(TrackFiles.title(files.get(0)));message("Playing your saved collection");}
