 private void applyAvatar(SessionAuth auth){if(accountAvatar==null)return;Artwork.init(this);String name=auth==null||auth.accountName.isBlank()?"Account":auth.accountName;accountAvatar.setContentDescription(auth==null?"Connect YouTube account":"YouTube account: "+name);com.bumptech.glide.Glide.with(this).clear(accountAvatar);if(auth==null||auth.accountName.isBlank())accountAvatar.setImageResource(R.drawable.ic_account);else accountAvatar.setImageDrawable(new TrackCoverDrawable(name));if(auth!=null&&AccountAvatar.allowed(auth.avatarUrl))com.bumptech.glide.Glide.with(this).load(auth.avatarUrl).circleCrop().override(dp(40),dp(40)).placeholder(new TrackCoverDrawable(name)).into(accountAvatar);}
 private void refreshAccountAvatar(){String scope=YouTubeSession.fingerprint(this),revision=YouTubeSession.revision(this);long checked=getSharedPreferences("music",0).getLong("avatarCheckedAt",0);if(avatarLoading){if(!scope.equals(avatarScope))applyAvatar(null);return;}if(!scope.equals(avatarScope))applyAvatar(null);if(scope.equals(avatarScope)&&revision.equals(avatarRevision)&&(!YouTubeSession.connected(this)||System.currentTimeMillis()-checked<86400000L))return;avatarLoading=true;avatarScope=scope;avatarRevision=revision;worker.execute(()->{try{SessionAuth auth=YouTubeSession.read(this);runOnUiThread(()->{if(!isDestroyed()&&scope.equals(YouTubeSession.fingerprint(this))&&revision.equals(YouTubeSession.revision(this)))applyAvatar(auth);});android.content.SharedPreferences prefs=getSharedPreferences("music",0);if(auth!=null&&!auth.avatarUrl.isEmpty()&&!scope.equals(prefs.getString("avatarCheckedScope","")))prefs.edit().putString("avatarCheckedScope",scope).putLong("avatarCheckedAt",System.currentTimeMillis()).apply();long age=System.currentTimeMillis()-prefs.getLong("avatarCheckedAt",0);if(auth!=null&&auth.complete()&&!auth.accountName.isBlank()&&(!scope.equals(prefs.getString("avatarCheckedScope",""))||age<0||age>86400000L)){SessionAuth refreshed=AccountMusic.verifyAccount(auth,"account-avatar");String next=YouTubeSession.updateProfile(this,scope,refreshed);if(next!=null){if(prefs.getString("musicScope","").equals(scope))prefs.edit().putString("musicScope",next).apply();prefs.edit().putString("avatarCheckedScope",next).putLong("avatarCheckedAt",System.currentTimeMillis()).apply();runOnUiThread(()->{if(isDestroyed()||!next.equals(YouTubeSession.fingerprint(this)))return;applyAvatar(refreshed);avatarScope=next;avatarRevision=YouTubeSession.revision(this);if(!next.equals(lastAccountScope)){lastAccountScope=next;cancelRecommendations();lastFeedAttempt=0;if("home".equals(page))showHome();}});}}}catch(Exception ignored){/* Keep the cached photo/initial when profile refresh is unavailable. */}finally{runOnUiThread(()->{avatarLoading=false;if(!isDestroyed()&&(!avatarScope.equals(YouTubeSession.fingerprint(this))||!avatarRevision.equals(YouTubeSession.revision(this)))){avatarScope="";refreshAccountAvatar();}});}});}
