ate();Runnable updater=new Runnable(){public void run(){if(!dialog.isShowing()||isDestroyed())return;state.setText(SmartDownloads.files(MainActivity.this).size()+" songs · "+SmartDownloads.bytes(MainActivity.this)/SmartDownloads.MIB+" MB\n"+SmartDownloads.status(MainActivity.this));progress.setProgress(prefs.getInt("smartProgress",0));handler.postDelayed(this,1000);}};dialog.setOnDismissListener(d->handler.removeCallbacks(updater));smartDialog=dialog;smartTick=updater;dialog.show();handler.post(updater);
