 private void syncSavedMusic(boolean afterSelection){
  if(!DownloadFolder.hasAccess(this)){pickFolder();return;}if(folderSaving){message("Saving your collection…");return;}if(DownloadService.busy){message("Let the current download finish, then save your collection.");return;}
  folderSaving=true;List<File> files=MusicRepository.files(this);message("Saving your collection to "+DownloadFolder.label(this)+"…");
  worker.execute(()->{int count=0;String failure="";try{for(File f:files){DownloadFolder.save(this,f);count++;}getSharedPreferences("music",0).edit().remove("folderSaveError").apply();}catch(Exception e){failure="Some files are still in the app. Check your download folder and retry saving.";}final int saved=count;final String error=failure;runOnUiThread(()->{folderSaving=false;if(isDestroyed())return;message(error.isEmpty()?saved+" files saved to "+DownloadFolder.label(this):error);if("library".equals(page))showLibrary();if(afterSelection&&pendingDownload!=null){Track t=pendingDownload;String format=pendingFormat;pendingDownload=null;beginDownload(t,format);} });});
 }
 private void trackMenu(File file){
  List<String> labels=new ArrayList<>();List<Runnable> actions=new ArrayList<>();labels.add(TrackFiles.audio(file)?"Play":"Open video");actions.add(()->openTrack(file));if(TrackFiles.audio(file)){for(boolean next:new boolean[]{true,false}){labels.add(next?"Play next":"Add to queue");actions.add(()->{LocalPlayerService player=LocalPlayerService.active;if(player==null||streaming){message("Play a saved song first to start a local queue.");return;}message(player.enqueue(file,next)?next?"Playing next: "+TrackFiles.title(file):"Added to local queue":"This song is already playing.");});}}
  if(TrackFiles.audio(file)||MusicTaste.track(this,TrackFiles.videoId(file))!=null){labels.add(MusicTaste.localLiked(this,file)?"Remove from liked songs":"Like song");actions.add(()->{MusicTaste.toggleLocal(this,file);profileChanged();message("Liked songs updated");});}
  if(SmartDownloads.owned(this,file)){labels.add("Keep permanently");actions.add(()->{SmartDownloads.keep(this,TrackFiles.videoId(file));message("Kept in your library · protected from smart rotation");if(DownloadFolder.hasAccess(this))worker.execute(()->{try{DownloadFolder.save(this,file);}catch(Exception e){runOnUiThread(()->message("Kept in app; saving to your folder needs attention."));}});});}
  labels.add("Save to download folder");actions.add(()->{if(!DownloadFolder.hasAccess(this)){pickFolder();return;}worker.execute(()->{try{DownloadFolder.save(this,file);runOnUiThread(()->message("Saved to "+DownloadFolder.label(this)));}catch(Exception e){runOnUiThread(()->message("Could not save to your folder. Open Settings to choose it again."));}});});labels.add("Save a copy elsewhere");actions.add(()->export(file));labels.add("Delete download");actions.add(()->confirmDeleteDownload(file));
  new com.google.android.material.dialog.MaterialAlertDialogBuilder(this).setTitle(TrackFiles.title(file)).setItems(labels.toArray(new String[0]),(d,which)->actions.get(which).run()).setNegativeButton("Close",null).show();
 }
 private void confirmDeleteDownload(File file){
  if(folderSaving){message("Wait for saving to your folder to finish, then try again.");return;}
  LinearLayout box=column();box.setPadding(dp(24),dp(8),dp(24),0);box.addView(text(TrackFiles.title(file),TYPE_TITLE));TextView detail=caption("Remove this app’s downloaded copy. You can download it again. Online song likes are kept.");detail.setPadding(0,dp(12),0,dp(8));box.addView(detail);CheckBox saved=new CheckBox(this);boolean hasSaved=DownloadFolder.savedUri(this,file)!=null;if(hasSaved){saved.setText("Also delete the copy in "+DownloadFolder.label(this));saved.setTextColor(COLOR_TEXT);box.addView(saved);}else box.addView(caption("Copies saved or imported elsewhere are kept."));
  androidx.appcompat.app.AlertDialog dialog=new com.google.android.material.dialog.MaterialAlertDialogBuilder(this).setTitle("Delete download?").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Delete",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{boolean external=hasSaved&&saved.isChecked();dialog.getButton(-1).setEnabled(false);LocalPlayerService player=LocalPlayerService.active;if(player!=null){if(player.path.equals(file.getAbsolutePath())){stopService(new Intent(this,LocalPlayerService.class));if(playerSheet!=null)playerSheet.dismiss();playing=false;position=duration=0;now.setText("Nothing playing");currentCover=null;updateBar();}else{int index=player.tracks().indexOf(file);if(index>=0)player.removeQueued(index);}}worker.execute(()->{String error="";try{LocalDownloads.remove(this,file,external);}catch(Exception e){error=DownloadService.message(e);}final String failure=error;runOnUiThread(()->{if(isDestroyed())return;dialog.dismiss();indexLocalCopies();if("library".equals(page))showLibrary();else if("home".equals(page))showHome();else showResults(queue);message(failure.isEmpty()?external?"Download and saved copy deleted":"Download removed · other copies kept":failure);});});}));dialog.show();
 }
