 private void beginDownload(Track track,String format){
  if(!DownloadFolder.hasAccess(this)){pendingDownload=track;pendingFormat=format;pickFolder();return;}
  getSharedPreferences("music",0).edit().putString("lastDownloadId",track.id).putString("lastDownloadTitle",track.title).apply();startForegroundService(new Intent(this,DownloadService.class).putExtra("id",track.id).putExtra("title",track.title).putExtra("format",format));message("");
 }

 private void chooseDownload(Track t){
  LinearLayout box=column();box.setPadding(dp(20),dp(8),dp(20),0);box.addView(text(t.title,16));Spinner formats=new Spinner(this);formats.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"MP3 audio","MP4 video (up to 720p)"}));box.addView(formats);TextView destination=caption("Save to: "+DownloadFolder.label(this));destination.setPadding(0,dp(8),0,dp(8));box.addView(destination);CheckBox consent=new CheckBox(this);consent.setText("I own this content or have permission to download it.");box.addView(consent);
  AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Download format").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Download",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(!consent.isChecked()){consent.setError("Confirm permission first");return;}String format=formats.getSelectedItemPosition()==0?"mp3":"mp4";dialog.dismiss();beginDownload(t,format);}));dialog.show();
 }
 private void startOnlineAudio(Track track,List<Track> source){
  try{handler.removeCallbacks(tapWarm);TapPreparation.prioritize(this,tapOwner,track);List<Track> tracks=new ArrayList<>(source);if(tracks.stream().noneMatch(t->t.id.equals(track.id)))tracks.add(0,track);closePreview();String encoded=TrackMetadata.encode(tracks);startForegroundService(new Intent(this,LocalPlayerService.class).setAction("online").putExtra("onlineQueue",encoded).putExtra("onlineId",track.id));now.setText(track.title);message("Loading online audio · background playback enabled");}catch(Exception e){message("Online audio could not start. Tap the song to retry.");}
 }
 private void playLocal(File f){handler.removeCallbacks(tapWarm);TapPreparation.cancel(tapOwner);closePreview();startForegroundService(new Intent(this,LocalPlayerService.class).setAction("open").putExtra("path",f.getAbsolutePath()).putExtra("sortByTitle","library".equals(page)&&libraryByName));now.setText(TrackFiles.title(f));if(playerSheet!=null&&playerSheet.isShowing())playerSheet.dismiss();message("Local audio · background playback enabled");}
 private void startPreview(Track track){startPreview(track,false);}
 private void startPreview(Track track,boolean keepOrder){
  if(!keepOrder&&!"search".equals(page)){submittedQuery="";searchCached=false;navigate("search");}
  if(streaming&&web!=null&&!previewFailed){if(!keepOrder){previewQueue=new ArrayList<>(queue);queueIndex=-1;for(int i=0;i<previewQueue.size();i++)if(previewQueue.get(i).id.equals(track.id)){queueIndex=i;break;}if(queueIndex<0){previewQueue=new ArrayList<>(List.of(track));queueIndex=0;}previewOrder.reset(previewQueue.size(),queueIndex,shuffled());}current=track;queueIndex=previewOrder.current();previewEnded=false;previewFailed=false;position=duration=0;playing=false;currentCover=artwork.get(track.id);now.setText(track.title);if(previewTrackTitle!=null)previewTrackTitle.setText(track.title);if(thumbnail!=null)loadThumbnail(track.id,token);getSharedPreferences("music",0).edit().putString("recommendationSeed",track.title).apply();message("Loading YouTube…");web.evaluateJavascript("loadTrack("+JSONObject.quote(track.id)+")",null);updateBar();return;}
  getSharedPreferences("music",0).edit().putString("recommendationSeed",track.title).apply();if(!"search".equals(page))navigate("search");stopService(new Intent(this,LocalPlayerService.class));closePreview();current=track;if(!keepOrder){previewQueue=new ArrayList<>(queue);queueIndex=previewQueue.indexOf(track);if(queueIndex<0){previewQueue=new ArrayList<>(List.of(track));queueIndex=0;}previewOrder.reset(previewQueue.size(),queueIndex,shuffled());}queueIndex=previewOrder.current();previewEnded=false;previewFailed=false;currentCover=artwork.get(track.id);if(playerSheet!=null&&playerSheet.isShowing())playerSheet.dismiss();streaming=true;token=UUID.randomUUID().toString();position=duration=0;playing=false;now.setText(track.title);message("Loading YouTube…");preview.setVisibility(View.VISIBLE);scroll.smoothScrollTo(0,0);
  web=new WebView(this);web.setBackgroundColor(Color.BLACK);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);web.addJavascriptInterface(new Bridge(),"Pocket");
  WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();
  web.setWebViewClient(new WebViewClient(){public WebResourceResponse shouldInterceptRequest(WebView w,WebResourceRequest r){return loader.shouldInterceptRequest(r.getUrl());}public boolean shouldOverrideUrlLoading(WebView w,WebResourceRequest r){if(!r.isForMainFrame())return false;return !"appassets.androidplatform.net".equals(r.getUrl().getHost());}public void onReceivedError(WebView w,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame())message("Preview unavailable. Check your connection.");}});
  thumbnail=new ImageView(this);thumbnail.setContentDescription(track.title);thumbnail.setImageResource(R.drawable.ic_music);previewTrackTitle=text(track.title,TYPE_TITLE);previewTrackTitle.setMaxLines(2);previewTrackTitle.setEllipsize(android.text.TextUtils.TruncateAt.END);previewMedia.addView(previewTrackTitle);previewMedia.addView(thumbnail,new LinearLayout.LayoutParams(-1,dp(72)));loadThumbnail(track.id,token);previewMedia.addView(web);setMode(videoMode);web.loadUrl("https://appassets.androidplatform.net/assets/preview.html?id="+track.id+"&token="+token+"&volume="+volume.getProgress());
 }
 private void setMode(boolean video){videoMode=video;getSharedPreferences("music",0).edit().putBoolean("video",video).apply();modeAudio.setSelected(!video);modeVideo.setSelected(video);modeAudio.setBackground(GlassTheme.button(this,!video));modeVideo.setBackground(GlassTheme.button(this,video));modeAudio.setTextColor(GlassTheme.TEXT);modeVideo.setTextColor(GlassTheme.TEXT);
  if(thumbnail!=null)thumbnail.setVisibility(video?View.GONE:View.VISIBLE);if(web!=null){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(video?-1:dp(200),video?Math.max(dp(200),(getResources().getDisplayMetrics().widthPixels-dp(48))*9/16):dp(200));web.setLayoutParams(p);}
 }
 private void closePreview(){previewFailed=false;token="";streaming=false;playing=false;position=duration=0;currentCover=null;if(web!=null){previewMedia.removeView(web);web.stopLoading();web.removeJavascriptInterface("Pocket");web.destroy();web=null;}previewMedia.removeAllViews();thumbnail=null;preview.setVisibility(View.GONE);updateBar();}
 private void command(String action,double value){if(web!=null)web.evaluateJavascript("command("+JSONObject.quote(action)+","+value+")",null);}
 private void togglePlay(){if(streaming&&previewFailed&&current!=null){startPreview(current,true);return;}if(streaming)command(playing?"pause":"play",0);else if(LocalPlayerService.active!=null){if(LocalPlayerService.active.pauseAvailable())LocalPlayerService.active.pause();else LocalPlayerService.active.play();}}
 private void step(int direction){if(streaming){if(direction<0&&position>3){command("seek",0);return;}int next=previewOrder.advance(direction,repeatMode(),false);if(next>=0)startPreview(previewQueue.get(next),true);else if(direction<0)command("seek",0);}else if(LocalPlayerService.active!=null){if(direction<0)LocalPlayerService.active.previous();else LocalPlayerService.active.next();}}
 private void updateBar(){if(toggle==null)return;updateFavorite();((PlayerButton)toggle).setPlaying(playing);toggle.setContentDescription(playing?"Pause":"Play");seek.setEnabled(duration>0);if(!seeking)seek.setProgress(duration>0?(int)(1000*position/duration):0);time.setText(clock(position)+" / "+clock(duration));if(currentCover!=lastPlayerCover){lastPlayerCover=currentCover;if(currentCover!=null)playerCover.setImageBitmap(currentCover);else playerCover.setImageResource(R.drawable.ic_music);}shuffleButton.setText(shuffled()?"Shuffle · On":"Shuffle");repeatButton.setText(repeatMode()==1?"Repeat · All":repeatMode()==2?"Repeat · One":"Repeat");if(playerSheet!=null&&playerSheet.isShowing())playerSheet.update(now.getText().toString(),playerHint.getText().toString(),currentCover,playing,position,duration,getSharedPreferences("music",0).getInt("volume",70),shuffled(),repeatMode());} private String clock(double seconds){int s=(int)Math.max(0,seconds);return String.format(Locale.ROOT,"%d:%02d",s/60,s%60);}
 private final class Bridge {@JavascriptInterface public void message(String raw){if(raw.length()>2000)return;handler.post(()->{try{JSONObject m=new JSONObject(raw);if(!streaming || !token.equals(m.optString("token")))return;if(m.has("videoId")&&current!=null&&!current.id.equals(m.optString("videoId")))return;String type=m.optString("type");if("status".equals(type)){position=m.optDouble("position",0);duration=m.optDouble("duration",0);int state=m.optInt("state");playing=state==1;if(playing){previewEnded=false;previewFailed=false;if(current!=null&&!current.id.equals(recordedPreview)){recordedPreview=current.id;MusicTaste.played(MainActivity.this,current);}}if(state==0&&!previewEnded){previewEnded=true;previewFinished();return;}MainActivity.this.message(state==3?"Buffering YouTube…":playing?"YouTube preview":"Preview paused · tap Play");updateBar();}else if("error".equals(type)){playing=false;previewFailed=true;MainActivity.this.message("Preview unavailable: "+m.optString("message")+" Tap Play to retry.");updateBar();}else if("blocked".equals(type))MainActivity.this.message("Tap Play inside the YouTube player.");}catch(JSONException ignored){}});}}
 private void loadArtwork(String id,ImageView target){Track track=knownMusic.get(id);if(track==null)track=new Track(id,target.getContentDescription()==null?"Music":target.getContentDescription().toString());Artwork.load(this,track,target,dp(SIZE_ART_LARGE));}
 private void loadThumbnail(String id,String expectedToken){if(thumbnail==null)return;Track track=current==null?new Track(id,"Music"):current;com.bumptech.glide.Glide.with(thumbnail).load(Artwork.url(track)).placeholder(new TrackCoverDrawable(track.title)).centerCrop().override(dp(200),dp(200)).listener(new com.bumptech.glide.request.RequestListener<android.graphics.drawable.Drawable>(){public boolean onLoadFailed(com.bumptech.glide.load.engine.GlideException e,Object model,com.bumptech.glide.request.target.Target<android.graphics.drawable.Drawable> target,boolean first){return false;}public boolean onResourceReady(android.graphics.drawable.Drawable resource,Object model,com.bumptech.glide.request.target.Target<android.graphics.drawable.Drawable> target,com.bumptech.glide.load.DataSource source,boolean first){if(token.equals(expectedToken)&&current!=null&&current.id.equals(id)&&resource instanceof android.graphics.drawable.BitmapDrawable){android.graphics.Bitmap original=((android.graphics.drawable.BitmapDrawable)resource).getBitmap();currentCover=android.graphics.Bitmap.createScaledBitmap(original,128,128,true).copy(android.graphics.Bitmap.Config.ARGB_8888,false);artwork.put(id,currentCover);updateBar();}return false;}}).into(thumbnail);}

 private void refreshPlayer(){
  if(SleepTimer.consumeExpired(this)){if(streaming)command("pause",0);if(LocalPlayerService.active!=null)LocalPlayerService.active.pause();message("Sleep timer finished.");}if(streaming&&LocalPlayerService.active!=null)closePreview();if(downloadsDialog!=null&&downloadsDialog.isShowing())updateDownloads();
  LocalPlayerService p=LocalPlayerService.active;
  miniPlayer.setVisibility(!keyboardVisible&&(streaming||p!=null)?View.VISIBLE:View.GONE);
  if(!streaming&&p!=null){now.setText(p.title);playing=p.pauseAvailable();position=p.position()/1000.0;duration=p.duration()/1000.0;currentCover=p.artwork;playerHint.setText("preparing".equals(p.state)?(p.online?"Loading online audio…":"Preparing audio…"):p.playing()?(p.networkPlayback?"Streaming online · background playback":"Playing from your library"):"Paused · tap to expand");if(!p.error.isEmpty())message(p.error);}
  else if(!streaming){playing=false;position=duration=0;currentCover=null;playerHint.setText("Tap a song to start");}
  if(streaming)playerHint.setText(previewFailed?"Preview failed · tap Play to retry":"YouTube preview · Tap for controls");
  String playerError=getSharedPreferences("music",0).getString("playerError","");if(!playerError.equals(lastPlayerError)){lastPlayerError=playerError;if(!playerError.isEmpty())message(playerError);}
  String download=DownloadService.busy?DownloadService.status:getSharedPreferences("music",0).getString("downloadStatus","");
  boolean failed=!DownloadService.busy&&(!getSharedPreferences("music",0).getString("downloadDetails","").isEmpty()||!getSharedPreferences("music",0).getString("folderSaveError","").isEmpty());
  if(!download.equals(lastDownload)){lastDownload=download;if(!DownloadService.busy){if("library".equals(page))showLibrary();else if("home".equals(page))showHome();if(!failed&&!download.isEmpty())Toast.makeText(this,download,Toast.LENGTH_LONG).show();}}
  updateBar();
 }
 private void tint(SeekBar s){s.setProgressTintList(android.content.res.ColorStateList.valueOf(ACCENT));s.setThumbTintList(android.content.res.ColorStateList.valueOf(ACCENT));}
 private boolean shuffled(){return getSharedPreferences("music",0).getBoolean("shuffle",false);}
 private int repeatMode(){return getSharedPreferences("music",0).getInt("repeat",0);}
 private void toggleShuffle(){boolean value=!shuffled();getSharedPreferences("music",0).edit().putBoolean("shuffle",value).apply();if(streaming)previewOrder.setShuffle(value);else if(LocalPlayerService.active!=null)LocalPlayerService.active.shuffle(value);updateBar();}
 private void cycleRepeat(){int mode=(repeatMode()+1)%3;getSharedPreferences("music",0).edit().putInt("repeat",mode).apply();if(!streaming&&LocalPlayerService.active!=null)LocalPlayerService.active.repeat(mode);updateBar();}
 private void setVolume(int percent){getSharedPreferences("music",0).edit().putInt("volume",percent).apply();if(streaming)command("volume",percent);else if(LocalPlayerService.active!=null)LocalPlayerService.active.volume(percent/100f);volume.setProgress(percent);}
 private void seekPlayback(double seconds){if(streaming)command("seek",seconds);else if(LocalPlayerService.active!=null)LocalPlayerService.active.seek((int)(seconds*1000));}
 private void showNowPlaying(){
  if(streaming){playerOptions.setVisibility(playerOptions.getVisibility()==View.GONE?View.VISIBLE:View.GONE);scroll.smoothScrollTo(0,0);return;}
  if(LocalPlayerService.active==null){message("Choose a track in Search or Library first.");return;}
  if(playerSheet==null)playerSheet=new NowPlayingSheet(this,new NowPlayingSheet.Actions(){public void toggle(){togglePlay();}public void step(int d){MainActivity.this.step(d);}public void seek(double seconds){seekPlayback(seconds);}public void volume(int value){setVolume(value);}public void shuffle(){toggleShuffle();}public void repeat(){cycleRepeat();}public void queue(){showQueue();}public void sleep(){showSleepTimer();}public void like(){toggleCurrentLike();}public boolean liked(){return currentLiked();}});
  playerSheet.show();refreshPlayer();
 }
 private void showQueue(){
  boolean previewSource=streaming;LocalPlayerService player=LocalPlayerService.active;if(!previewSource&&player==null){message("Your queue is empty. Play a track first.");return;}
  List<Integer> order=previewSource?previewOrder.sequence():player.queueOrder();List<File> local=previewSource?List.of():player.tracks();boolean online=!previewSource&&player.online;List<Track> songs=online?player.onlineTracks():List.of();int currentIndex=previewSource?previewOrder.current():player.queueIndex();List<String> names=new ArrayList<>();for(int index:order)names.add((index==currentIndex?"▶  ":"")+(previewSource?previewQueue.get(index).title:online?songs.get(index).title:TrackFiles.title(local.get(index))));
  new AlertDialog.Builder(this).setTitle(previewSource?"Video preview queue":online?"Online audio queue":"Local queue").setItems(names.toArray(new String[0]),(dialog,which)->{int index=order.get(which);String title=previewSource?previewQueue.get(index).title:online?songs.get(index).title:TrackFiles.title(local.get(index));new AlertDialog.Builder(this).setTitle(title).setItems(index==currentIndex?new String[]{"Play"}:new String[]{"Play","Move next","Remove from queue"},(d,action)->{if(previewSource){if(!streaming)return;if(action==0){previewOrder.select(index);startPreview(previewQueue.get(index),true);}else if(action==1)previewOrder.playNext(index);else if(previewOrder.remove(index))previewQueue.remove(index);}else if(LocalPlayerService.active==player){if(action==0)player.playQueued(index);else if(action==1)player.moveNext(index);else player.removeQueued(index);}if(action>0)showQueue();}).setNegativeButton("Close",null).show();}).setNegativeButton("Close",null).show();
 }

 private void previewFinished(){
  if(repeatMode()==PlaybackOrder.ONE){command("seek",0);command("play",0);return;}
  int next=previewOrder.advance(1,repeatMode(),true);if(next>=0)startPreview(previewQueue.get(next),true);else{playing=false;message("Preview queue finished · tap Play to replay");updateBar();}
 }

 private static void copy(InputStream in,OutputStream out)throws IOException{byte[] buffer=new byte[32768];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);}
 private void importAudio(){if(settingsDialog!=null)settingsDialog.dismiss();Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,40);}
 private void export(File f){exportFile=f;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType(f.getName().endsWith(".mp4")?"video/mp4":"audio/*").putExtra(Intent.EXTRA_TITLE,f.getName()).addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,41);}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK || data==null || data.getData()==null){if(request==42){pendingDownload=null;message("Folder selection cancelled. Nothing was downloaded.");}return;}Uri uri=data.getData();if(request==42){try{DownloadFolder.remember(this,uri,data.getFlags());syncSavedMusic(true);}catch(Exception e){pendingDownload=null;message("Folder access was not saved. Please select a writable folder again.");}return;}File source=exportFile;message("Copying file…");worker.execute(()->{try{if(request==40){String name="Imported audio "+System.currentTimeMillis()+".mp3";try(android.database.Cursor c=getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null && c.moveToFirst())name=c.getString(0).replaceAll("[^a-zA-Z0-9 ._()\\[\\]-]","_");}File target=new File(MusicRepository.folder(this),name);if(target.exists())throw new IOException("A file with this name already exists.");File temporary=new File(target.getPath()+".part");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temporary)){if(in==null)throw new IOException("Cannot open audio");copy(in,out);}if(!temporary.renameTo(target))throw new IOException("Cannot finish import");}else if(request==41 && source!=null){try(InputStream in=new FileInputStream(source);OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Cannot open export destination");copy(in,out);}}runOnUiThread(()->{message("File saved.");page="library";showLibrary();});}catch(Exception e){runOnUiThread(()->message("File copy failed: "+DownloadService.message(e)));}});}
 protected void onStart(){super.onStart();SmartDownloads.requestIfDue(this);refreshAccountAvatar();String scope=Recommendations.scope(this);if(!scope.equals(lastAccountScope)){lastAccountScope=scope;lastFeedAttempt=0;cancelRecommendations();lastRecommendationRequest="";recommendationsError="";Recommendations.clear(this);if("home".equals(page))showHome();else if("search".equals(page)&&submittedQuery.isEmpty())showResults(queue);}visible=true;if(smartDialog!=null&&smartDialog.isShowing()&&smartTick!=null)handler.post(smartTick);scheduleVisibleSongs();handler.removeCallbacks(tick);handler.post(tick);if(web!=null)web.onResume();}
 protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);if(pendingDownload!=null){out.putString("pendingId",pendingDownload.id);out.putString("pendingTitle",pendingDownload.title);out.putString("pendingFormat",pendingFormat);}}
 protected void onStop(){if(smartTick!=null)handler.removeCallbacks(smartTick);handler.removeCallbacks(tapWarm);TapPreparation.cancel(tapOwner);NativeMotion.finish(results);visible=false;handler.removeCallbacks(tick);if(web!=null){command("pause",0);web.onPause();}super.onStop();}
 protected void onDestroy(){if(smartDialog!=null)smartDialog.dismiss();handler.removeCallbacks(tapWarm);TapPreparation.cancel(tapOwner);if(tasteDialog!=null)tasteDialog.dismiss();cancelSearch();cancelRecommendations();searchWorker.shutdownNow();searchControl.shutdown();if(downloadsDialog!=null)downloadsDialog.dismiss();discovery.shutdownNow();new Thread(()->com.yausername.youtubedl_android.YoutubeDL.getInstance().destroyProcessById("recommendations")).start();new Thread(()->com.yausername.youtubedl_android.YoutubeDL.getInstance().destroyProcessById("account-recommendations")).start();if(playerSheet!=null)playerSheet.dismiss();if(settingsDialog!=null)settingsDialog.dismiss();closePreview();worker.shutdownNow();images.shutdownNow();new Thread(()->com.yausername.youtubedl_android.YoutubeDL.getInstance().destroyProcessById("search")).start();handler.removeCallbacksAndMessages(null);super.onDestroy();}
